class AppSessionFactoryProvider {
    private static SessionFactory instance;
    static synchronized SessionFactory get(String profile) {
        if (instance == null) {
            instance = buildSessionFactory(profile);
            Runtime.getRuntime().addShutdownHook(new Thread(instance::close));
        }
        return instance;
    }
    static boolean healthCheck() {
        try (Session s = get("dev").openSession()) {
            s.createNativeQuery("select 1", Integer.class).getSingleResult();
            return true;
        } catch (Exception e) { return false; }
    }
}
